import json
from itertools import product
from datetime import date
D=json.loads(context)
qs=D['quotes']; skus=D['skus']; vs={v['id']:v for v in D['vendors']}
opts={s:[q for q in qs if q['sku']==s and q['quality']=='approved' and q['units']>=skus[s]['demand'] and q['units']<=skus[s]['demand']+2 and q['arrival']<=skus[s]['deadline']] for s in skus}
best=None
for combo in product(*(opts[s] for s in skus)):
    bysku={q['sku']:q for q in combo}
    if any(q['needs_same_vendor_sku'] and bysku[q['needs_same_vendor_sku']]['vendor']!=q['vendor'] for q in combo): continue
    vendors={q['vendor'] for q in combo}
    if len(vendors)<3 or sum(q['carbon'] for q in combo)>D['carbon_cap']: continue
    totals={v:sum(q['units'] for q in combo if q['vendor']==v) for v in vendors}
    if any(totals[v]>vs[v]['unit_cap'] for v in vendors): continue
    cost=0
    for v in vendors:
        subset=[q for q in combo if q['vendor']==v]
        gross=sum(q['units']*q['unit_cents'] for q in subset)
        merch=gross
        if totals[v]>=vs[v]['tier_units']:
            # integer half-up rounding of gross*(10000-bps)/10000
            numer=gross*(10000-vs[v]['tier_bps'])
            merch=(numer+5000)//10000
        subtotal=merch
        if gross<vs[v]['free_shipping_gross']: subtotal+=vs[v]['shipping_cents']
        if len({q['sku'] for q in subset})>=2 and merch>=vs[v]['rebate_merchandise_min']: subtotal-=vs[v]['rebate_cents']
        cost+=subtotal
    if best is None or cost<best[0]: best=(cost,[q['id'] for q in combo])
print(best)
print(FINAL(str(best[0])) )
